package com.taskhub.domain.vehicle;
import com.taskhub.api.ApiResponse; import com.taskhub.domain.identity.IdentityModels.Actor; import java.util.Map; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class VehicleControlController { private final VehicleControlService service; public VehicleControlController(VehicleControlService s){service=s;} @PostMapping("/tasks/{id}/go") public ApiResponse<Map<String,Object>> go(@AuthenticationPrincipal Actor a,@PathVariable String id,@RequestHeader("Idempotency-Key") String k,@RequestBody ControlModels.Input i){return ApiResponse.success(service.go(a,id,k,i));} @PostMapping("/tasks/{id}/cancel") public ApiResponse<Map<String,Object>> cancel(@AuthenticationPrincipal Actor a,@PathVariable String id,@RequestHeader("Idempotency-Key") String k,@RequestBody ControlModels.Input i){return ApiResponse.success(service.cancel(a,id,k,i));} }
